using System.Globalization;
using System.Security;
using System.Text;
using BooksApi.Data;

namespace BooksApi.Services;

/// <summary>
/// Fallback cover for books an admin created without uploading an image.
/// (Built-in books ship hand-tuned SVG covers generated by tools/content-builder.)
/// Same palettes as the built-in covers, so new books still look like part of the series.
/// </summary>
public static class CoverRenderer
{
    private static readonly (string Bg, string Ink, string Accent, string Soft)[] Palettes =
    [
        ("#1f3a5f", "#f4ede1", "#e8b04a", "#2b4c7a"),
        ("#b4352a", "#fbf3e6", "#2a1d16", "#c4493d"),
        ("#efe5d1", "#211d18", "#b4352a", "#e2d5bc"),
        ("#2f4a3a", "#f1e9da", "#d9a441", "#3c5c49"),
        ("#211d18", "#efe5d3", "#d0603f", "#332c25"),
        ("#e6b85c", "#211d18", "#8f2a20", "#d9a845"),
        ("#5e2a40", "#f6ead9", "#e7a977", "#71354f"),
        ("#3a3d58", "#f4f1de", "#e07a5f", "#474b6b"),
    ];

    public static string Render(Book book)
    {
        var seed = Hash(book.CoverKey + book.Title);
        var p = Palettes[seed % Palettes.Length];
        var georgian = book.Title.Any(c => c is >= 'Ⴀ' and <= 'ჿ');
        var font = georgian
            ? "'Noto Serif Georgian','Sylfaen','BPG Glaho','DejaVu Serif',serif"
            : "'Spectral','Georgia','Times New Roman',serif";

        var lines = Wrap(book.Title, georgian ? 13 : 16, 3);
        var longest = lines.Max(l => l.Length);
        var size = Math.Clamp(500.0 / Math.Max(8, longest) * (georgian ? 1.0 : 1.15), 24, 48);
        var lineH = size * 1.15;
        var top = 474 - (lines.Count - 1) * lineH;

        var sb = new StringBuilder();
        sb.Append($"""<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 600" width="400" height="600" role="img" aria-label="{Esc(book.Title)}">""");
        sb.Append($"""<rect width="400" height="600" fill="{p.Bg}"/>""");
        // motif: nested arches, like the windows of an old Georgian church
        var cx = 200 + (seed % 40) - 20;
        sb.Append($"""<circle cx="{cx}" cy="190" r="128" fill="{p.Soft}"/>""");
        for (var i = 0; i < 4; i++)
        {
            var w = 150 - i * 34;
            var h = 220 - i * 40;
            var x = cx - w / 2;
            var y = 300 - h;
            sb.Append($"""<path d="M{x} 300V{y + w / 2}A{w / 2} {w / 2} 0 0 1 {x + w} {y + w / 2}V300" fill="none" stroke="{(i % 2 == 0 ? p.Ink : p.Accent)}" stroke-width="{(i == 0 ? "4" : "2.5")}"/>""");
        }
        sb.Append($"""<circle cx="{cx}" cy="128" r="9" fill="{p.Accent}"/>""");
        for (var i = 0; i < lines.Count; i++)
            sb.Append($"""<text x="200" y="{F(top + i * lineH)}" text-anchor="middle" font-family="{font}" font-size="{F(size)}" font-weight="600" fill="{p.Ink}">{Esc(lines[i])}</text>""");
        sb.Append($"""<rect x="180" y="490" width="40" height="2" fill="{p.Accent}"/>""");
        var authorFont = georgian ? "'Noto Sans Georgian','Sylfaen',sans-serif" : "'Spectral','Georgia',serif";
        var author = georgian ? book.Author : book.Author.ToUpperInvariant();
        sb.Append($"""<text x="200" y="518" text-anchor="middle" font-family="{authorFont}" font-size="15" letter-spacing="{(georgian ? "1" : "2.5")}" fill="{p.Ink}" opacity="0.85">{Esc(author)}</text>""");
        sb.Append($"""<text x="200" y="566" text-anchor="middle" font-family="'Spectral','Georgia',serif" font-size="10" letter-spacing="3.2" fill="{p.Ink}" opacity="0.55">ANBANI</text>""");
        sb.Append("""<rect width="16" height="600" fill="#000" opacity="0.14"/><rect x="16" width="2" height="600" fill="#fff" opacity="0.12"/>""");
        sb.Append("</svg>");
        return sb.ToString();
    }

    private static List<string> Wrap(string text, int maxChars, int maxLines)
    {
        var lines = new List<string>();
        var current = "";
        foreach (var word in text.Split(' ', StringSplitOptions.RemoveEmptyEntries))
        {
            if (current.Length > 0 && current.Length + 1 + word.Length > maxChars)
            {
                lines.Add(current);
                current = word;
            }
            else current = current.Length == 0 ? word : current + " " + word;
        }
        if (current.Length > 0) lines.Add(current);
        if (lines.Count == 0) lines.Add(text);
        if (lines.Count > maxLines) lines = [.. lines.Take(maxLines - 1), string.Join(' ', lines.Skip(maxLines - 1))];
        return lines;
    }

    private static int Hash(string s)
    {
        unchecked
        {
            var h = (int)2166136261;
            foreach (var c in s) h = (h ^ c) * 16777619;
            return h & 0x7fffffff;
        }
    }

    private static string Esc(string s) => SecurityElement.Escape(s) ?? "";
    private static string F(double d) => d.ToString("0.#", CultureInfo.InvariantCulture);
}
